"""Checks on this machine's generated files, its run from blank tape and the pass map (CI runs them,
.github/workflows/tests.yml).

usage: python3 bb6-1RB1RA_1RC1LB_1LD0RA_1LB0LE/tests/test_machine.py
"""
import json
import os
import re
import subprocess
import sys
import tempfile
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
REPO = os.path.dirname(ROOT)
TOOLS = os.path.join(REPO, "tools")
sys.path.insert(0, os.path.join(TOOLS, "py"))
sys.path.insert(0, os.path.join(TOOLS, "pages"))
sys.path.insert(0, os.path.join(ROOT, "py"))
sys.path.insert(0, os.path.join(ROOT, "lean"))

import build_status  # noqa: E402
import passmap  # noqa: E402
import rules  # noqa: E402
from bbtools.invariants import conserved  # noqa: E402
from bbtools.leangen import machine_lean  # noqa: E402
from bbtools.machine import Machine, Run, Tape, records  # noqa: E402
from bbtools.symtm import prove, rules_file  # noqa: E402

M = "1RB1RA_1RC1LB_1LD0RA_1LB0LE_1LF1LD_---0LD"
SHORT = "1RB1RA_1RC1LB_1LD0RA_1LB0LE"
MACHINE = Machine.parse(M)


def tmrun():
    out = os.path.join(tempfile.mkdtemp(), "tmrun")
    subprocess.run(["gcc", "-O2", "-o", out, os.path.join(TOOLS, "c", "tmrun.c")], check=True)
    return out


class TestGenerated(unittest.TestCase):
    def test_machine_lean_current(self):
        with open(os.path.join(ROOT, "lean", "Machine.lean")) as f:
            src = f.read()
        doc = "The six-state machine this folder studies; whether it halts from blank tape is open."
        self.assertEqual(src, machine_lean(M, "BB6d", doc))

    def test_rules_lean_current(self):
        ths = [prove(M, name, a, b, doc=doc)[0] for name, a, b, doc in rules.RULES]
        want = rules_file("Machine", "BB6d", ths, f"Rules of {M}, generated by `rules.py`; do not edit by hand.")
        with open(os.path.join(ROOT, "lean", "Rules.lean")) as f:
            self.assertEqual(f.read(), want)

    def test_page_current(self):
        with open(os.path.join(ROOT, "status.json")) as f:
            spec = json.load(f)
        spec.setdefault("source", f"bb6-{SHORT}/status.json")
        with open(os.path.join(REPO, "pages", SHORT, "proof-status.html")) as f:
            self.assertEqual(f.read(), build_status.build(spec, spec.get("home", "../index.html")))


class TestRun(unittest.TestCase):
    def test_machine(self):
        self.assertEqual(MACHINE.halting_transitions(), ["F0"])

    def test_first_pass(self):
        """The configuration of `blank_at_17` in lean/Blank.lean."""
        r = Run(MACHINE)
        r.run(17)
        self.assertEqual(r.config_str(), "1^2 0 1^2 A>0")

    def test_halt_shape(self):
        """`halt_shape`: 0 E>0 halts on its second step, with the halting transition counted (bbchallenge)."""
        tp = Tape()
        tp.set(-2, 1)
        r = Run(MACHINE, state=4, tape=tp, head=0)
        self.assertTrue(r.run(10))
        self.assertEqual(r.steps, 2)

    def test_no_small_invariant(self):
        """No conserved a*ones + b*pos + W[state] modulo 2 to 8 (tools/py/bbtools/invariants.py)."""
        for mod in range(2, 9):
            self.assertEqual(conserved(MACHINE, mod), [], mod)

    def test_c_agrees(self):
        """tools/c/tmrun gives the same records as the Python simulator."""
        got = subprocess.run([tmrun(), M, "100000", "records", "80"],
                             check=True, capture_output=True, text=True).stdout.splitlines()
        py = [f"{t} {side} {r.tape.hi - r.tape.lo} {r.config_str()}" for t, side, r in records(MACHINE, 100000)]
        self.assertEqual(got[:-1], py[:80])


class TestPassMap(unittest.TestCase):
    def test_closed_form_against_machine(self):
        """The closed form agrees with the machine on random block lists (stop block 1 left out)."""
        tried, skipped = passmap.check(600, 6, seed=7)
        self.assertGreater(tried, 500)

    def test_halt_case(self):
        """Last block odd, all others even: the sweep runs off the left end and the machine halts."""
        for y in ([2, 1], [4, 2, 3], [2, 2, 2, 5]):
            self.assertEqual(passmap.passmap(y), passmap.HALT)
            self.assertEqual(passmap.run_pass(y)[0], passmap.HALT)

    def test_stop_block_one(self):
        """A stop block of 1 is outside the closed form; the machine there gives an odd number of ones."""
        got, _, clean = passmap.run_pass([5, 7, 1, 1])
        self.assertEqual((got, clean), ([9, 10], True))
        self.assertIsNone(passmap.passmap([5, 7, 1, 1]))

    def test_orbit_against_c(self):
        """Every pass start in the first 10^8 steps (C records ending in A>0) is the orbit of the closed form."""
        out = subprocess.run([tmrun(), M, "100000000", "records", "100000"],
                             check=True, capture_output=True, text=True).stdout.splitlines()
        starts = []
        for line in out[:-1]:
            cfg = line.split(None, 3)[3]
            if cfg.endswith("A>0"):
                toks = cfg[:-3].split()
                self.assertTrue(all(re.fullmatch(r"1(\^\d+)?|0", t) for t in toks), cfg)
                starts.append([int(t[2:]) if "^" in t else 1 for t in toks if t[0] == "1"])
        self.assertGreater(len(starts), 400)
        self.assertEqual(starts, list(passmap.orbit(len(starts))))

    def test_orbit_sums(self):
        """Pass n starts with 4(n+1) ones, and no stop block is 1, for the first 20,000 passes."""
        for i, y in enumerate(passmap.orbit(20000)):
            self.assertEqual(sum(y), 4 * (i + 1))
            j = passmap.stop_index(y)
            self.assertTrue(j >= 1 and (j == len(y) or y[j - 1] > 1), y)


if __name__ == "__main__":
    unittest.main(verbosity=2)
